var t=`1125-new-england-lobster-roll`;var i=`world-1125`;var o=`US`;var s=`northern-america`;var l=4;var r=31;var a={en:`New England Lobster Roll`,ua:`Лобстер-рол по-новоанглійськи`};var d={en:`New England Lobster Roll is a dish from United States prepared with lobster, celery stalk, green onion, mayonnaise. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Лобстер-рол по-новоанглійськи, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: лобстер, стебло селери, зелена цибуля, майонез. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Poach the listed ingredients in barely simmering liquid for about 14 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 14 хвилин до готовності й м’якості.`,t:[`poaching`],m:14,i:[[`lobster`,750,`g`],[`water`,850,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`celery-stalk`,130,`g`],[`green-onion`,35,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`mayonnaise`,125,`g`],[`lemon-juice`,35,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`hot-dog-bun`,4,`pcs`],[`unsalted-butter`,45,`g`],[`lettuce`,120,`g`]]}];var u={slug:t,id:i,country:`US`,region:s,servings:4,minutes:31,title:a,text:d,steps:g};export{o as country,u as default,i as id,r as minutes,s as region,l as servings,t as slug,g as steps,d as text,a as title};